    root=base.OUT/'friction_single_history_sanity';names=['original_width32','expanded_width96_fourier'];summaries={name:json.loads((root/name/'summary.json').read_text()) for name in names};histories={name:json.loads((root/name/'history.json').read_text())['history'] for name in names};assert all(value['actual_optimizer_updates']==1600 for value in summaries.values());assert all(value['physical_metrics']['id']=='friction_001' for value in summaries.values());groups=[group['group'] for group in summaries[names[0]]['physical_metrics']['physical_groups']] # Enforce matched data and actual optimizer-update counts before comparing capacities.
    result={'status':'SINGLE_HISTORY_CAPACITY_COMPARISON_COMPLETE','native_history':'friction_001','native_entities':697,'native_frames':33,'optimizer_updates_per_model':1600,'test_or_ood_fields_opened':False,'scope':'overfit diagnostic only; same actual loading history, all nodes and IPs, full cold rollout','changed_factors':['width32 versus96','depth3 versus4','coordinate Fourier inputs added to expanded model'],'compute_budget_note':'Optimizer-update counts match; parameter count and wall cost differ, so this is not an equal-FLOP comparison.','models':{name:{'parameters':value['parameters'],'seconds':value['seconds'],'best_normalized_RMSE':value['best_normalized_RMSE'],'all_group_accuracy_pass':value['physical_metrics']['accuracy_pass'],'physical_groups':value['physical_metrics']['physical_groups'],'reload_max_absolute_difference':value['checkpoint_reload_max_absolute_difference']} for name,value in summaries.items()}} # Preserve useful capacity evidence without attributing it to one isolated architectural factor or generalization.
    refinement=root/'expanded_width96_fourier_refined2000/summary.json' # Discover only the explicitly registered follow-up optimization diagnostic.
    if refinement.exists(): value=json.loads(refinement.read_text());result['targeted_continuation_to_2000_updates']={'parameters':198255,'actual_total_optimizer_updates':value['actual_total_optimizer_updates'],'selected_total_optimizer_update':value['selected_total_optimizer_update'],'worst_group_error_over_gate':value['worst_group_error_over_gate'],'all_group_accuracy_pass':value['physical_metrics']['accuracy_pass'],'physical_groups':value['physical_metrics']['physical_groups'],'seconds_continuation':value['seconds_continuation'],'invariants':value.get('invariants'),'objective_change':'Cauchy stress and interface shear loss weight3; all other fields retainweight1; thresholds unchanged'} # Keep its changed objective separate from the matched1600-update capacity comparison.
    base.write(root/'comparison.json',result) # Regenerate the complete measured diagnostic summary from immutable per-run results.
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'savefig.facecolor':'white'});figure,axes=plt.subplots(1,2,figsize=(12.8,4.4));colors=['#b24f24','#167a9e'];labels=['21,199 parameters; width32','198,255 parameters; width96 + Fourier inputs'] # Make actual capacity and input differences visible in the figure.
    for name,color,label in zip(names,colors,labels): axes[0].plot([row['optimizer_updates'] for row in histories[name]],[row['cold_rollout_normalized_RMSE'] for row in histories[name]],color=color,marker='o',markersize=3,label=label) # Plot only actual complete-history reconstructions recorded during optimization.
    axes[0].set(xlabel='Actual optimizer updates',ylabel='Known-history cold-rollout normalized RMSE',title='All 697 FE/IP entities, all 33 native frames');axes[0].grid(alpha=.18);axes[0].legend(fontsize=8) # Distinguish temporal cold rollout from teacher-forced one-step fitting.
    positions=np.arange(len(groups));width=.36 # Align complete physical groups between both capacities.
    for offset,name,color in zip([-width/2,width/2],names,colors): rows=summaries[name]['physical_metrics']['physical_groups'];lookup={row['group']:row for row in rows};axes[1].bar(positions+offset,[lookup[group]['relative_L2']/lookup[group]['threshold'] for group in groups],width,color=color,label=name) # Show all failures relative to their predeclared physical-field error gates.
    axes[1].axhline(1.,color='#333333',linestyle='--',linewidth=1.2);axes[1].set_xticks(positions,[group.replace('_','\n') for group in groups],fontsize=8);axes[1].set(ylabel='Relative field error / registered threshold',title='Below 1 meets the field-error gate');axes[1].grid(axis='y',alpha=.18);figure.suptitle('Single-history overfit diagnostic — one known friction separation/recontact path',fontsize=12);figure.tight_layout();figure.savefig(root/'single_history_capacity.png',dpi=180);figure.savefig(root/'single_history_capacity.svg');plt.close(figure) # Save a reproducible measured-data visualization without implying unseen-history success.
